          "badge": "UNIT 4 — REVISION DESK",
          "title": "Requisites of Valid Adoption (Ss. 6–11 HAMA) & Inter-country Adoption",
          "anchorId": "revision",
          "file": "Family/DU_Unit_III_Maintenance_Under_Hindu_Law.html",
          "type": "table",
